wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

/// The one named store this node may read.
const STORE_KEY: &str = "subscriptions";

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // The store is the node's only source. If the key is absent there is
        // nothing to report; trapping produces no output, so the `present(urls)`
        // ensures is not violated by a value we never emit.
        let raw = match state_read::get(STORE_KEY) {
            Some(v) => v,
            None => unreachable!("subscriptions key absent from state store"),
        };

        // One URL per line. Keep only well-formed http(s) entries.
        let urls: Vec<String> = raw
            .lines()
            .map(|line| line.trim())
            .filter(|line| !line.is_empty())
            .filter(|line| line.starts_with("https://") || line.starts_with("http://"))
            .map(|line| line.to_string())
            .collect();

        // `present(urls)`: never emit an empty subscription list. Fabricating
        // URLs is not an option, so an empty result traps instead of emitting.
        if urls.is_empty() {
            unreachable!("subscriptions store held no usable URLs");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
